head.script:
/**
 * @target WebSquare5 Controller Script
 */
scwin.onpageload = function() {
    // [요구사항 2] 공통 코드 매핑 객체 초기화 (코드: 라벨)
    scwin.itemCodeMap = {
        "01": "기획/전략 수립",
        "02": "화면 설계 및 기획",
        "03": "UI/UX 컴포넌트 개발",
        "04": "백엔드 API 연동",
        "05": "품질 테스트 및 QA",
        "06": "서버 배포 및 모니터링",
        "07": "사용자 매뉴얼 작성"
    };

    // 외부 클릭 시 플로팅 레이어 닫기 이벤트 등록
    document.addEventListener("mousedown", scwin.fn_handleOutsideClick);
    // [추가] 외부 스크롤 시 플로팅 레이어 닫기 이벤트 등록 (capture: true로 그리드 및 부모 컨테이너 스크롤 감지)
    window.addEventListener("scroll", scwin.fn_handleOutsideScroll, true);
};

scwin.onpageunload = function() {
    // 페이지 언로드 시 이벤트 및 동적 DOM 메모리 해제
    document.removeEventListener("mousedown", scwin.fn_handleOutsideClick);
    window.removeEventListener("scroll", scwin.fn_handleOutsideScroll, true);
    var el = document.getElementById("ws_floating_multicheck");
    if (el && el.parentNode) {
        el.parentNode.removeChild(el);
    }
};

/**
 * [요구사항 2] customFormatter: 줄바꿈 포맷팅 함수
 * "01,02,05" 형태의 코드 문자열을 라벨로 변환 후 <br/> 태그로 연결하여 반환
 */
scwin.fn_formatMultiCheck = function(data, formattedData, rowIndex, colIndex) {
    if (!data || typeof data !== "string" || data.trim() === "") {
        // [수정] 엑셀 다운로드 시 placeholder('(선택 없음)') 노출 방지 -> 빈 값("") 출력
        if (scwin._isExcelDownloading) {
            return "";
        }
        return '<span style="color:#94a3b8; font-style:italic;">(선택 없음)</span>';
    }

    var codeList = data.split(",");
    var labelList = [];

    for (var i = 0; i < codeList.length; i++) {
        var code = codeList[i].trim();
        if (code !== "") {
            // 코드 매핑 객체에서 라벨 탐색 (매핑 없으면 코드 원본 노출)
            var label = scwin.itemCodeMap[code] || code;
            labelList.push(label);
        }
    }

    if (labelList.length === 0) {
        return '<span style="color:#94a3b8; font-style:italic;">(선택 없음)</span>';
    }

    // HTML 태그 <br/>로 결합하여 셀 내부 개행 유도
    return labelList.join("<br/>");
};

/**
 * [호환성 헬퍼] WebSquare5 버전별 안전한 GridView 셀 TD DOM Element 취득 함수
 * WebSquare5 공식 엔진은 'getCellDom' 메서드를 제공하지 않으므로,
 * 1) 표준 셀 ID ({gridId}_cell_{row}_{col})
 * 2) 클릭 이벤트 객체(event.target.closest('td'))
 * 3) getCellElement API 순서로 fallback 처리합니다.
 */
scwin.fn_getGridCellDom = function(gridObj, row, col) {
    var gridId = (typeof gridObj.getID === "function") ? gridObj.getID() : gridObj.id;

    // 1순위: WebSquare5 정식 셀 DOM ID 패턴 ({gridId}_cell_{row}_{col})
    var cellDom = document.getElementById(gridId + "_cell_" + row + "_" + col);
    if (cellDom) return cellDom;

    // 2순위: 브라우저 이벤트 객체의 타겟에서 TD 탐색
    var evt = window.event;
    if (evt && evt.target) {
        var td = evt.target.closest ? evt.target.closest("td") : null;
        if (td) return td;
    }

    // 3순위: 일부 SP 버전에 존재하는 getCellElement API 체크
    if (typeof gridObj.getCellElement === "function") {
        return gridObj.getCellElement(row, col);
    }

    return null;
};

/**
 * [탭 제어] TabControl 탭 클릭 시 열려 있는 플로팅 레이어 닫기
 */
scwin.tac_main_ontabclick = function(tabIndex, tabId) {
    scwin.fn_closeMultiCheckLayer();
};

/**
 * [요구사항 3] GridView 셀 클릭 이벤트 (메인 그리드 - 담당 업무)
 * 'taskCodes' 컬럼 클릭 시 플로팅 다중 체크 레이어 호출
 */
scwin.grd_main_oncellclick = function(row, col) {
    var colId = grd_main.getColumnID(col);

    // 담당 업무(taskCodes) 컬럼 클릭 시만 드롭다운 팝업 실행
    if (colId !== "taskCodes") {
        return;
    }

    // WebSquare5 안전한 셀 DOM Element 획득 (getCellDom 대체)
    var cellDom = scwin.fn_getGridCellDom(grd_main, row, col);
    if (!cellDom) return;

    // 현재 셀의 선택된 코드 목록 추출
    var rawValue = dlt_sample.getCellData(row, colId) || "";
    var selectedCodes = rawValue ? rawValue.split(",").map(function(c) { return c.trim(); }) : [];

    // 플로팅 레이어 오픈 (대상 DataList: dlt_sample 지정)
    scwin.fn_openMultiCheckLayer(cellDom, row, colId, selectedCodes, dlt_sample);
};

/**
 * [탭 2] GridView 셀 클릭 이벤트 (보조 그리드 - 프로젝트 팀 현황)
 * 'taskCodes' 컬럼 클릭 시 동일한 플로팅 다중 체크 레이어 호출
 */
scwin.grd_team_oncellclick = function(row, col) {
    var colId = grd_team.getColumnID(col);

    // 팀 핵심 과업(taskCodes) 컬럼 클릭 시만 드롭다운 팝업 실행
    if (colId !== "taskCodes") {
        return;
    }

    var cellDom = scwin.fn_getGridCellDom(grd_team, row, col);
    if (!cellDom) return;

    var rawValue = dlt_team.getCellData(row, colId) || "";
    var selectedCodes = rawValue ? rawValue.split(",").map(function(c) { return c.trim(); }) : [];

    // 플로팅 레이어 오픈 (대상 DataList: dlt_team 지정)
    scwin.fn_openMultiCheckLayer(cellDom, row, colId, selectedCodes, dlt_team);
};

/**
 * 플로팅 검색/체크 레이어 생성 및 좌표 배치 함수
 * @param {Element} cellDom - 클릭된 그리드 TD 엘리먼트
 * @param {Number} targetRow - 대상 행 인덱스
 * @param {String} colId - 대상 컬럼 ID
 * @param {Array} selectedCodes - 기선택된 코드 배열
 * @param {Object} targetDataList - 데이터 반영 대상 WebSquare DataList 객체
 */
scwin.fn_openMultiCheckLayer = function(cellDom, targetRow, colId, selectedCodes, targetDataList) {
    targetDataList = targetDataList || dlt_sample;
    var layer = document.getElementById("ws_floating_multicheck");
    if (!layer) {
        layer = document.createElement("div");
        layer.id = "ws_floating_multicheck";
        layer.className = "ws-multicheck-layer";
        document.body.appendChild(layer);
    }

    // 현재 작업 대상 행, 컬럼 및 DataList 정보 캐싱
    layer.dataset.targetRow = targetRow;
    layer.dataset.targetColId = colId;
    layer.targetDataList = targetDataList;

    // [핵심] 검색 전/후 체크 항목 유실 방지를 위한 상태 맵(Map) 초기화
    layer.checkedCodeMap = {};
    for (var k = 0; k < selectedCodes.length; k++) {
        if (selectedCodes[k]) {
            layer.checkedCodeMap[selectedCodes[k]] = true;
        }
    }

    // 1. 레이어 템플릿 마크업 주입
    layer.innerHTML = 
        '<div class="ws-multicheck-header">' +
            '<input type="text" id="ws_multicheck_input" class="ws-multicheck-search" placeholder="업무명 또는 코드 검색..." autocomplete="off" />' +
        '</div>' +
        '<div class="ws-multicheck-body" id="ws_multicheck_list"></div>' +
        '<div class="ws-multicheck-footer">' +
            '<button type="button" class="ws-btn-apply" id="ws_btn_apply">적용</button>' +
            '<button type="button" class="ws-btn-close" id="ws_btn_close">닫기</button>' +
        '</div>';

    // 2. 체크박스 항목 리스트 선행 렌더링 (실제 콘텐츠 높이 측정을 위함)
    scwin.fn_renderCheckList("", layer.checkedCodeMap);

    // 3. 레이어 임시 노출 및 너비 지정
    layer.style.display = "block";
    layer.style.visibility = "hidden"; // 정확한 좌표 계산 완료 전 깜빡임 방지
    layer.style.width = Math.max(cellDom.getBoundingClientRect().width, 260) + "px";

    // 4. 셀 좌표 및 실제 렌더링된 레이어 높이 측정
    var rect = cellDom.getBoundingClientRect();
    var leftPos = rect.left + window.scrollX;
    var layerHeight = layer.offsetHeight || 280;
    var spaceBelow = window.innerHeight - rect.bottom; // 셀 아래 여유 공간
    var spaceAbove = rect.top;                          // 셀 위 여유 공간
    var topPos;

    // [요구사항] 밑에 공간이 적으면 바로 위에 레이어 표시
    if (spaceBelow < layerHeight && spaceAbove >= layerHeight) {
        // 상단 공간이 충분하고 하단 공간이 부족한 경우 -> 셀 '바로 위'에 4px 여백으로 도킹
        topPos = rect.top + window.scrollY - layerHeight - 4;
    } else if (spaceBelow < layerHeight && spaceAbove > spaceBelow) {
        // 상/하 둘 다 부족하지만 상단 공간이 더 넓은 경우 -> 뷰포트 최상단 마진 고려하여 위로 배치
        topPos = Math.max(rect.top + window.scrollY - layerHeight - 4, window.scrollY + 10);
    } else {
        // 기본값: 하단 공간이 충분한 경우 -> 셀 '바로 아래'에 4px 여백으로 도킹
        topPos = rect.bottom + window.scrollY + 4;
    }

    layer.style.top = topPos + "px";
    layer.style.left = leftPos + "px";
    layer.style.visibility = "visible"; // 최종 위치 확정 후 노출

    // 검색 Input 자동 포커스 및 실시간 필터링 이벤트 등록
    var searchInput = document.getElementById("ws_multicheck_input");
    searchInput.focus();
    searchInput.addEventListener("input", function(e) {
        var keyword = e.target.value;
        // [핵심] DOM이 아닌 layer.checkedCodeMap을 전달하므로 검색 전/후 체크 항목이 완벽히 유지됨
        scwin.fn_renderCheckList(keyword, layer.checkedCodeMap);
    });

    // [적용] 버튼 클릭 시
    document.getElementById("ws_btn_apply").onclick = function() {
        // DOM이 아닌 상태 맵(layer.checkedCodeMap)에서 전체 선택 코드 추출
        var finalCodes = [];
        for (var code in layer.checkedCodeMap) {
            if (layer.checkedCodeMap[code]) {
                finalCodes.push(code);
            }
        }
        var combinedValue = finalCodes.join(",");

        // WebSquare DataList 데이터 갱신 -> customFormatter 자동 재호출되어 화면 갱신
        var dlt = layer.targetDataList || dlt_sample;
        dlt.setCellData(targetRow, colId, combinedValue);
        scwin.fn_closeMultiCheckLayer();
    };

    // [닫기] 버튼 클릭 시
    document.getElementById("ws_btn_close").onclick = function() {
        scwin.fn_closeMultiCheckLayer();
    };
};

/**
 * 검색 키워드에 따라 체크박스 목록 실시간 필터링 및 자동 정렬 렌더링
 * [요구사항] 
 * 1) 선택(체크)된 항목은 목록 상단(위)으로 자동 정렬
 * 2) 검색 전 체크 항목과 검색 후 체크 항목이 완벽히 동기화 및 유지
 */
scwin.fn_renderCheckList = function(keyword, checkedCodeMap) {
    var listContainer = document.getElementById("ws_multicheck_list");
    if (!listContainer) return;

    listContainer.innerHTML = "";
    var lowerKeyword = (keyword || "").toLowerCase().trim();

    // 1. 검색 조건에 일치하는 항목 수집
    var items = [];
    for (var code in scwin.itemCodeMap) {
        var label = scwin.itemCodeMap[code];

        // 검색 조건 검사: 라벨명 또는 코드에 키워드 포함 시 노출
        if (lowerKeyword === "" || label.toLowerCase().indexOf(lowerKeyword) > -1 || code.indexOf(lowerKeyword) > -1) {
            var isChecked = !!(checkedCodeMap && checkedCodeMap[code]);
            items.push({
                code: code,
                label: label,
                isChecked: isChecked
            });
        }
    }

    // 2. [체크 항목 상단 자동 정렬]
    // isChecked가 true인 항목이 위로(-1), false인 항목이 아래로(1)
    items.sort(function(a, b) {
        if (a.isChecked && !b.isChecked) return -1;
        if (!a.isChecked && b.isChecked) return 1;
        return a.code.localeCompare(b.code); // 동일 체크 상태 내에서는 코드순 정렬
    });

    // 3. DOM 요소 생성 및 렌더링
    for (var i = 0; i < items.length; i++) {
        var it = items[i];
        var itemLabel = document.createElement("label");
        itemLabel.className = "ws-multicheck-item" + (it.isChecked ? " is-checked" : "");
        itemLabel.innerHTML = 
            '<input type="checkbox" value="' + it.code + '" ' + (it.isChecked ? 'checked' : '') + ' />' +
            '<span>[' + it.code + '] ' + it.label + '</span>';

        // [핵심] 체크 토글 시 상태 맵(checkedCodeMap)에 즉시 동기화
        itemLabel.querySelector("input").addEventListener("change", function(e) {
            var codeVal = this.value;
            if (this.checked) {
                checkedCodeMap[codeVal] = true;
                this.closest("label").classList.add("is-checked");
            } else {
                delete checkedCodeMap[codeVal];
                this.closest("label").classList.remove("is-checked");
            }
        });

        listContainer.appendChild(itemLabel);
    }

    if (items.length === 0) {
        listContainer.innerHTML = '<div style="padding:15px; text-align:center; color:#94a3b8;">일치하는 항목이 없습니다.</div>';
    }
};

/**
 * 현재 체크된 코드 배열 수집
 */
scwin.fn_getCurrentlyCheckedCodes = function() {
    var checkedList = [];
    var checkboxes = document.querySelectorAll("#ws_multicheck_list input[type='checkbox']:checked");
    for (var i = 0; i < checkboxes.length; i++) {
        checkedList.push(checkboxes[i].value);
    }
    return checkedList;
};

/**
 * 플로팅 레이어 숨김 처리
 */
scwin.fn_closeMultiCheckLayer = function() {
    var layer = document.getElementById("ws_floating_multicheck");
    if (layer) {
        layer.style.display = "none";
    }
};

/**
 * 팝업 영역 바깥 클릭 시 자동 닫힘 처리
 */
scwin.fn_handleOutsideClick = function(e) {
    var layer = document.getElementById("ws_floating_multicheck");
    if (!layer || layer.style.display !== "block") return;

    // 클릭 위치가 레이어 내부가 아니고 그리드 셀도 아닐 경우 닫기
    if (!layer.contains(e.target) && !e.target.closest(".cell-multiline")) {
        scwin.fn_closeMultiCheckLayer();
    }
};

/**
 * [추가] 팝업 영역 바깥 스크롤 시 자동 닫힘 처리
 * - 레이어 내부 스크롤(예: 체크박스 목록 스크롤)은 유지
 * - 외부 윈도우 스크롤 또는 그리드 내부 스크롤 발생 시 즉시 닫기
 */
scwin.fn_handleOutsideScroll = function(e) {
    var layer = document.getElementById("ws_floating_multicheck");
    if (!layer || layer.style.display !== "block") return;

    // 스크롤 이벤트 발생 위치가 레이어 내부이면 무시 (체크 목록 스크롤 허용)
    if (e.target && (e.target === layer || layer.contains(e.target))) {
        return;
    }

    scwin.fn_closeMultiCheckLayer();
};

/**
 * [엑셀 다운로드] WebSquare5 공식 API를 활용한 전달사항 + 다중 탭 그리드 통합 다운로드
 * - 복수 시트/그리드 지원: WebSquare.util.multipleExcelDownload 사용
 * - useFormat: true 옵션으로 커스텀 포맷터 줄바꿈 및 라벨 변환 상태 그대로 엑셀 셀에 반영
 * - [수정] 전달사항이 비어있거나 placeholder 상태인 경우 상단 infoArr 삽입을 완전히 생략하여 placeholder 노출 방지
 * - [수정] scwin._isExcelDownloading 플래그를 통해 미선택 셀의 '(선택 없음)' placeholder 노출 방지
 */
scwin.btn_excel_onclick = function() {
    var rawNotice = (txa_notice.getValue() || "").trim();
    var placeholderText = (typeof txa_notice.getPlaceholder === "function" ? txa_notice.getPlaceholder() : "") || "전달사항을 입력하세요...";

    // 전달사항이 비어있거나 placeholder 텍스트와 일치하면 엑셀 상단 공통 전달사항 행 제외
    var hasNotice = (rawNotice !== "" && rawNotice !== placeholderText && rawNotice !== "(입력된 전달사항 없음)" && rawNotice !== "(전달사항 없음)");
    var fileName = "통합_배정_및_팀현황_" + new Date().toISOString().slice(0,10).replace(/-/g, "") + ".xlsx";

    var infoArr1 = hasNotice ? [
        { row: 0, col: 0, rowSpan: 2, colSpan: 4, text: "[공통 전달사항]\n" + rawNotice, style: "background-color:#eff6ff; font-weight:bold; color:#1d4ed8; text-align:left;" }
    ] : [];

    var infoArr2 = hasNotice ? [
        { row: 0, col: 0, rowSpan: 2, colSpan: 5, text: "[공통 전달사항]\n" + rawNotice, style: "background-color:#eff6ff; font-weight:bold; color:#1d4ed8; text-align:left;" }
    ] : [];

    var sheet1Options = {
        gridId: "grd_main",
        sheetName: "담당업무배정",
        useFormat: true,
        useSubTotal: false,
        colDataFilter: true,
        bodyStyle: "font-family:Malgun Gothic; font-size:10pt; line-height:1.5;",
        headerStyle: "background-color:#f1f5f9; font-weight:bold; font-family:Malgun Gothic;",
        infoArr: infoArr1
    };

    var sheet2Options = {
        gridId: "grd_team",
        sheetName: "프로젝트팀현황",
        useFormat: true,
        useSubTotal: false,
        colDataFilter: true,
        bodyStyle: "font-family:Malgun Gothic; font-size:10pt; line-height:1.5;",
        headerStyle: "background-color:#f1f5f9; font-weight:bold; font-family:Malgun Gothic;",
        infoArr: infoArr2
    };

    // 엑셀 다운로드 중 플래그 활성화 -> 커스텀 포맷터에서 (선택 없음) placeholder 제외 처리
    scwin._isExcelDownloading = true;

    try {
        if (window.WebSquare && WebSquare.util && typeof WebSquare.util.multipleExcelDownload === "function") {
            WebSquare.util.multipleExcelDownload([sheet1Options, sheet2Options], { fileName: fileName });
        } else if (typeof grd_main.advancedExcelDownload === "function") {
            // 단일 그리드 fallback
            grd_main.advancedExcelDownload({
                fileName: fileName,
                useFormat: true,
                infoArr: sheet1Options.infoArr
            });
        } else {
            alert("WebSquare 엑셀 다운로드 엔진을 호출할 수 없습니다. (WebSquare 환경에서 실행해 주세요)");
        }
    } finally {
        setTimeout(function() {
            scwin._isExcelDownloading = false;
        }, 1500);
    }
};

/**
 * [프리뷰] 전달사항 및 모든 탭의 데이터를 화면에 보이는 상태 그대로 모달 팝업으로 출력
 */
scwin.btn_preview_onclick = function() {
    var rawNotice = (txa_notice.getValue() || "").trim();
    var placeholderText = (typeof txa_notice.getPlaceholder === "function" ? txa_notice.getPlaceholder() : "") || "전달사항을 입력하세요...";
    var hasNotice = (rawNotice !== "" && rawNotice !== placeholderText && rawNotice !== "(입력된 전달사항 없음)" && rawNotice !== "(전달사항 없음)");

    // 1. 전달사항 렌더링 (전달사항이 있는 경우만 박스 노출, 없으면 박스 숨김)
    var noticeBox = document.getElementById("ws_preview_notice_box");
    if (hasNotice) {
        if (noticeBox) noticeBox.style.display = "block";
        var previewNotice = document.getElementById("ws_preview_notice_text");
        if (previewNotice) previewNotice.innerText = rawNotice;
    } else {
        if (noticeBox) noticeBox.style.display = "none";
    }

    // 1. 전달사항 렌더링
    var previewNotice = document.getElementById("ws_preview_notice_text");
    if (previewNotice) {
        previewNotice.innerText = notice;
    }

    // 2. 탭 1 (담당 업무 배정) 데이터 테이블 생성
    var t1Body = document.getElementById("ws_preview_tbl1_body");
    if (t1Body) {
        t1Body.innerHTML = "";
        var dlt1Data = dlt_sample.getAllJSON();
        for (var i = 0; i < dlt1Data.length; i++) {
            var row = dlt1Data[i];
            var tr = document.createElement("tr");
            tr.innerHTML = 
                '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1;">' + (row.seq || "") + '</td>' +
                '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1; font-weight:500;">' + (row.userName || "") + '</td>' +
                '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1; line-height:1.5;">' + scwin.fn_formatMultiCheck(row.taskCodes) + '</td>' +
                '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1;">' + (row.remark || "") + '</td>';
            t1Body.appendChild(tr);
        }
    }

    // 3. 탭 2 (프로젝트 팀 현황) 데이터 테이블 생성
    var t2Body = document.getElementById("ws_preview_tbl2_body");
    if (t2Body) {
        t2Body.innerHTML = "";
        var dlt2Data = dlt_team.getAllJSON();
        for (var j = 0; j < dlt2Data.length; j++) {
            var r = dlt2Data[j];
            var tr2 = document.createElement("tr");
            tr2.innerHTML = 
                '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1;">' + (r.seq || "") + '</td>' +
                '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1; font-weight:500;">' + (r.teamName || "") + '</td>' +
                '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1;">' + (r.leader || "") + '</td>' +
                '<td style="text-align:left; padding:6px; border:1px solid #cbd5e1; line-height:1.5;">' + scwin.fn_formatMultiCheck(r.taskCodes) + '</td>' +
                '<td style="text-align:center; padding:6px; border:1px solid #cbd5e1; font-weight:bold; color:#2563eb;">' + (r.progress || "") + '</td>';
            t2Body.appendChild(tr2);
        }
    }

    // 모달 열기
    var modal = document.getElementById("ws_preview_modal_wrap");
    if (modal) modal.style.display = "flex";
};

/**
 * 프리뷰 모달 닫기
 */
scwin.fn_closePreviewModal = function() {
    var modal = document.getElementById("ws_preview_modal_wrap");
    if (modal) modal.style.display = "none";
};
